# ! [feature (return_position_impl_trait_in_trait)] trait AsyncIterator { type Item ; async fn next (& mut self) -> Option < Self :: Item > ; } struct YieldingRange { counter : u32 , stop : u32 , } impl AsyncIterator for YieldingRange { type Item = u32 ; async fn next (& mut self) -> Option < Self :: Item > { if self . counter == self . stop { None } else { let c = self . counter ; self . counter += 1 ; tokio :: task :: yield_now () . await ; Some (c) } } } # [tokio :: main] async fn main () { let mut x = YieldingRange { counter : 0 , stop : 10 } ; while let Some (v) = x . next () . await { println ! ("Hi: {v}") ; } }